SELECT UTC_TIMESTAMP(3) observed_utc;
SELECT a.id,a.ownership,c.cred_format FROM account a LEFT JOIN account_credential c ON c.account_id=a.id AND c.tenant_id=a.tenant_id AND c.deleted_at IS NULL WHERE a.id IN(821,999,1038);
SELECT 'feed' source,a.account_id,a.task_id,a.send_status,t.status,t.task_status,t.deleted_at FROM feed_task_account a JOIN feed_task t ON t.id=a.task_id AND t.tenant_id=a.tenant_id WHERE a.account_id IN(821,999,1038) ORDER BY a.id;
SELECT 'contact' source,a.account_id,a.task_id,a.state,t.is_enabled,t.run_status,t.deleted_at FROM contact_friend_task_account a JOIN contact_friend_task t ON t.id=a.task_id AND t.tenant_id=a.tenant_id WHERE a.account_id IN(821,999,1038) ORDER BY a.id;
SELECT 'join' source,a.account_id,a.join_task_id,a.status item_status,a.dispatch_state,t.status task_status,t.deleted_at FROM join_task_result a JOIN join_task t ON t.id=a.join_task_id AND t.tenant_id=a.tenant_id WHERE a.account_id IN(821,999,1038) ORDER BY a.id;
SELECT 'normal_group_creation' source,a.creator_account_id,a.task_id,a.status item_status,a.current_step,a.dispatch_status,t.status task_status,t.deleted_at FROM normal_group_creation_item a JOIN normal_group_creation_task t ON t.id=a.task_id AND t.tenant_id=a.tenant_id WHERE a.creator_account_id IN(821,999,1038) ORDER BY a.id;
SELECT 'group_creation_marketing' source,a.account_id,a.task_id,a.status item_status,t.status task_status,t.deleted_at FROM group_creation_marketing_item a JOIN group_creation_marketing_task t ON t.id=a.task_id AND t.tenant_id=a.tenant_id WHERE a.account_id IN(821,999,1038) ORDER BY a.id;
SELECT id,tenant_id,REGEXP_REPLACE(name,'[0-9]{8,}','[REDACTED]') name,REGEXP_REPLACE(remark,'[0-9]{8,}','[REDACTED]') remark,generation FROM group_data_package WHERE deleted_at IS NULL AND (name REGEXP '测试|受控|test|accept|验收|自有' OR remark REGEXP '测试|受控|test|accept|验收|自有') ORDER BY id DESC LIMIT 30;
SELECT id,tenant_id,REGEXP_REPLACE(package_name,'[0-9]{8,}','[REDACTED]') package_name,REGEXP_REPLACE(remark,'[0-9]{8,}','[REDACTED]') remark,phone_count FROM data_package WHERE deleted_at IS NULL AND (package_name REGEXP '测试|受控|test|accept|验收|自有' OR remark REGEXP '测试|受控|test|accept|验收|自有') ORDER BY id DESC LIMIT 30;
